WITH lines AS (SELECT id, service, log_ts, latency_ms, status_code, k, attr_value FROM app_logs LATERAL VIEW EXPLODE(context) t AS k, attr_value) SELECT id, service, log_ts, k, attr_value, COUNT(status_code) OVER (ORDER BY CAST(log_ts AS BIGINT) RANGE BETWEEN 1800 PRECEDING AND CURRENT ROW) status_code_count_30m, LAG(latency_ms, 2) OVER (PARTITION BY YEAR(log_ts), service ORDER BY status_code, id, k) prev_latency_ms, AVG(status_code) OVER (PARTITION BY DATE_TRUNC('YEAR', log_ts), service ORDER BY status_code, id, k ROWS BETWEEN 3 PRECEDING AND CURRENT ROW) status_code_avg_3, LEAD(status_code, 1) OVER (PARTITION BY k ORDER BY log_ts, id, k) next_status_code, DENSE_RANK() OVER (PARTITION BY k ORDER BY status_code DESC) status_code_dense_rank FROM lines
